package com.adc.application;
import com.adc.domain.invoicing.InvoiceRules;
import com.adc.domain.shared.DomainFailure;
import com.adc.identity.IdentityGate;
import com.adc.infrastructure.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.json.JsonMapper;

@Service @Transactional(isolation=Isolation.READ_COMMITTED,rollbackFor=Exception.class)
public class InvoiceService implements ReceiptPolicy {
    private final AtomicCommandExecutor commands;private final IdentityGate gate;private final InvoiceStore store;private final ClinicalTreatmentStore clinical;private final AppointmentTransitionStore appointments;private final AuditWriter audit;private static final JsonMapper JSON=JsonMapper.builder().build();
    public InvoiceService(AtomicCommandExecutor commands,IdentityGate gate,InvoiceStore store,ClinicalTreatmentStore clinical,AppointmentTransitionStore appointments,AuditWriter audit){this.commands=commands;this.gate=gate;this.store=store;this.clinical=clinical;this.appointments=appointments;this.audit=audit;}
    private void issueAccess(IdentityGate.Identity actor,long appointment){gate.requireStaff(actor,"CASHIER","invoiceAppointment",appointments.facts(appointment).clinic());}
    private void readAccess(IdentityGate.Identity actor,long invoice){long clinic=appointments.facts(store.appointment(invoice)).clinic();for(String role:List.of("CASHIER","HEADQUARTERS"))try{if(gate.staffClinics(actor,role,"getInvoice").contains(clinic))return;}catch(DomainFailure denied){if(denied.status()!=403)throw denied;}throw new DomainFailure(403,"ACCESS_DENIED");}
    @SuppressWarnings("unchecked")private Map<String,Object> verified(long invoice){var view=store.view(invoice);var items=(List<Map<String,Object>>)view.get("items");if(items.isEmpty())throw new DomainFailure(422,"INVALID_INVOICE_SOURCE");var amounts=new ArrayList<java.math.BigDecimal>();for(var item:items){InvoiceRules.line((String)item.get("standard_units"),(String)item.get("unit_price"),(String)item.get("subtotal"));amounts.add(new java.math.BigDecimal((String)item.get("subtotal")));}if(InvoiceRules.sum(amounts).compareTo(new java.math.BigDecimal((String)view.get("total_amount")))!=0)throw new DomainFailure(422,"INVALID_INVOICE_SOURCE");return view;}
    public Map<String,Object> issue(AtomicCommandExecutor.Command command,long appointment)throws Exception{
        var result=commands.execute(command,actor->issueAccess(actor,appointment),actor->{clinical.lock(appointment,null);issueAccess(actor,appointment);var facts=appointments.facts(appointment);Long invoice=store.existing(appointment);if(invoice!=null){if(!facts.status().equals("INVOICED"))throw new DomainFailure(409,"INVOICE_HISTORY_INCONSISTENT");}else{var lines=store.lines(appointment);InvoiceRules.completed(facts.status(),!lines.isEmpty());for(var line:lines){if(line.appointment()!=appointment || line.dentist()==null || line.name()==null || line.name().isBlank() || line.units()==null || line.price()==null || line.subtotal()==null)throw new DomainFailure(422,"INVALID_INVOICE_SOURCE");InvoiceRules.line(line.units().toPlainString(),line.price().toPlainString(),line.subtotal().toPlainString());if(store.used(line.applied()))throw new DomainFailure(422,"INVALID_INVOICE_SOURCE");}invoice=store.create(appointment,lines,InvoiceRules.sum(lines.stream().map(InvoiceStore.Line::subtotal).toList()),actor.subjectId(),command.key());}store.ensureBill(invoice);return new AtomicCommandExecutor.Result(JSON.writeValueAsString(List.of("Invoice:"+invoice,"Appointment:"+appointment)),JSON.writeValueAsString(Map.of("invoice_id",Long.toString(invoice))),200,"Invoice",Long.toString(invoice),List.of(facts.clinic()));});var actor=gate.authenticate(command.token(),command.client());authorize(actor,"invoiceAppointment",result.refs());return verified(Long.parseLong(JSON.readTree(result.summary()).get("invoice_id").asText()));
    }
    public Map<String,Object> preview(String token,String client,long appointment,String request){var actor=gate.authenticate(token,client);issueAccess(actor,appointment);if(!appointments.facts(appointment).status().equals("COMPLETED"))throw new DomainFailure(409,"COMPLETED_VISIT_REQUIRED");var view=store.preview(appointment);audit.success(actor,"previewInvoice","Appointment",Long.toString(appointment),List.of(appointments.facts(appointment).clinic()),request);return view;}
    public Map<String,Object> get(String token,String client,long invoice,String request){var failedActor=new IdentityGate.Identity[1];AuditWriter.onRollback(audit,()->failedActor[0],"getInvoice",request);var actor=gate.authenticate(token,client);failedActor[0]=actor;readAccess(actor,invoice);var view=verified(invoice);audit.success(actor,"getInvoice","Invoice",Long.toString(invoice),List.of(appointments.facts(store.appointment(invoice)).clinic()),request);return view;}
    @Override @Transactional(propagation=Propagation.NOT_SUPPORTED)public Set<String> operations(){return Set.of("invoiceAppointment");}
    @Override public void authorize(IdentityGate.Identity actor,String operation,String refs){if(!operation.equals("invoiceAppointment"))throw new DomainFailure(403,"ACCESS_DENIED");gate.staffClinics(actor,"CASHIER",operation);if(refs!=null)for(var node:JSON.readTree(refs)){String ref=node.asText();if(ref.startsWith("Invoice:"))issueAccess(actor,store.appointment(Long.parseLong(ref.substring(8))));else if(ref.startsWith("Appointment:"))issueAccess(actor,Long.parseLong(ref.substring(12)));else throw new DomainFailure(403,"ACCESS_DENIED");}}
}

